use xiom.io;
fn calc_tip(amount: Int, percent: Int) -> Int {
  return amount * percent / 100;
}

fn calc_total(amount: Int, tip: Int) -> Int {
  return amount + tip;
}

fn main() {
  let bill: Int = 80;
  let tip: Int = calc_tip(bill, 15);
  let total: Int = calc_total(bill, tip);
  io.println("Bill: ");
  io.println("Bill: $80");
  io.println("Tip: ");
  io.println("Tip: $12");
  io.println("Total: ");
  io.println("Total: $92");
}
